package com.mybank.pbac.controller;
import com.mybank.pbac.model.Industry; import com.mybank.pbac.service.IndustryService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/industries") public class IndustryController{private final IndustryService s;public IndustryController(IndustryService s){this.s=s;}@GetMapping public List<Industry> all(){return s.all();}@GetMapping("/{id}") public Industry one(@PathVariable Long id){return s.one(id);}@PostMapping public Industry add(@Valid @RequestBody Industry x){x.setId(null);return s.save(null,x);}@PutMapping("/{id}") public Industry edit(@PathVariable Long id,@Valid @RequestBody Industry x){return s.save(id,x);}@DeleteMapping("/{id}") public void disable(@PathVariable Long id){s.disable(id);}}
